import { TRACO, svg, circulo, elipse, cam, ret, COR } from './primitivas.js'

// Os amigos: cabeça redonda e corpinho, cada bicho com orelhas e detalhes próprios.
// Piscam de tempos em tempos.
const CONTORNO = 'stroke="#3b2a1a" stroke-width="2.5"'

const BICHOS = {
  cachorro: { cor: '#d9a066', escuro: '#8a5a2b', orelha: 'caida', focinho: '#f6dcc0' },
  gato: { cor: '#f4a261', escuro: '#d57d36', orelha: 'ponta', focinho: '#fbe3c8', bigode: true },
  coelho: { cor: '#f4eadb', escuro: '#f4a3b5', orelha: 'longa', focinho: '#ffffff' },
  urso: { cor: '#b9835a', escuro: '#8a5a2b', orelha: 'redonda', focinho: '#e8c9a0' },
  raposa: { cor: '#f08a3c', escuro: '#c8631a', orelha: 'ponta', focinho: '#ffffff', bochechas: true },
  panda: { cor: '#ffffff', escuro: '#2b2b2b', orelha: 'redonda', manchas: true, focinho: '#ffffff' },
  sapo: { cor: '#7ac74f', escuro: '#4f9a2c', orelha: 'sapo', focinho: '#c9ec9a' },
  macaco: { cor: '#a9743f', escuro: '#7d5128', orelha: 'redonda', focinho: '#f0d2a4', rosto: true },
}

function orelhas(b) {
  switch (b.orelha) {
    case 'caida':
      return (
        elipse(20, 52, 10, 20, b.escuro, `transform="rotate(12 20 52)" ${CONTORNO}`) +
        elipse(80, 52, 10, 20, b.escuro, `transform="rotate(-12 80 52)" ${CONTORNO}`)
      )
    case 'ponta':
      return (
        cam('M20 40 L26 6 L48 24 Z', b.cor, TRACO, 2.5) +
        cam('M80 40 L74 6 L52 24 Z', b.cor, TRACO, 2.5) +
        cam('M27 30 L29 15 L40 25 Z', b.escuro, 'none', 0) +
        cam('M73 30 L71 15 L60 25 Z', b.escuro, 'none', 0)
      )
    case 'longa':
      return (
        elipse(36, 18, 8, 22, b.cor, CONTORNO) +
        elipse(64, 18, 8, 22, b.cor, CONTORNO) +
        elipse(36, 20, 4, 15, b.escuro) +
        elipse(64, 20, 4, 15, b.escuro)
      )
    case 'redonda':
      return (
        circulo(22, 26, 12, b.escuro, CONTORNO) +
        circulo(78, 26, 12, b.escuro, CONTORNO) +
        circulo(22, 26, 6, b.focinho) +
        circulo(78, 26, 6, b.focinho)
      )
    case 'sapo':
      return (
        circulo(30, 26, 13, b.cor, CONTORNO) + circulo(70, 26, 13, b.cor, CONTORNO)
      )
    default:
      return ''
  }
}

function rosto(b, fechado) {
  const olho = (x, y) =>
    fechado
      ? cam(`M${x - 6} ${y} Q${x} ${y + 6} ${x + 6} ${y}`)
      : circulo(x, y, 5.5, TRACO) + circulo(x + 1.8, y - 2, 1.8, '#fff')
  let s = ''
  if (b.manchas) {
    s += elipse(35, 54, 9, 11, '#2b2b2b', 'transform="rotate(20 35 54)"')
    s += elipse(65, 54, 9, 11, '#2b2b2b', 'transform="rotate(-20 65 54)"')
  }
  if (b.rosto) s += elipse(50, 66, 22, 18, b.focinho) + circulo(38, 50, 11, b.focinho) + circulo(62, 50, 11, b.focinho)
  if (b.bochechas) s += cam('M18 66 Q34 58 50 74 Q66 58 82 66 Q72 90 50 90 Q28 90 18 66Z', b.focinho, 'none', 0)
  else if (!b.rosto && b.orelha !== 'sapo') s += elipse(50, 74, 15, 11, b.focinho)

  const olhoY = b.orelha === 'sapo' ? 28 : 54
  const olhoX = b.orelha === 'sapo' ? [30, 70] : [36, 64]
  if (b.orelha === 'sapo') {
    s += circulo(30, 28, 9, '#fff', CONTORNO) + circulo(70, 28, 9, '#fff', CONTORNO)
    s += (fechado ? cam('M23 29 H37 M63 29 H77') : circulo(31, 29, 4.5, TRACO) + circulo(69, 29, 4.5, TRACO))
  } else {
    s += olho(olhoX[0], olhoY) + olho(olhoX[1], olhoY)
  }
  s += b.orelha === 'sapo' ? cam('M30 70 Q50 86 70 70') : ''
  if (b.orelha !== 'sapo') {
    s += elipse(50, 68, 6, 4.5, TRACO)
    s += cam('M50 72 V77 M42 79 Q50 85 58 79')
  }
  if (b.bigode) s += cam('M20 68 L36 70 M20 76 L36 74 M80 68 L64 70 M80 76 L64 74', 'none', TRACO, 1.8)
  s += elipse(24, 70, 6, 4, COR.rosa, 'opacity="0.55"') + elipse(76, 70, 6, 4, COR.rosa, 'opacity="0.55"')
  return s
}

function desenhar(b, fechado) {
  return svg(
    orelhas(b) +
      ret(26, 84, 48, 16, b.cor, 8, CONTORNO) +
      circulo(50, 56, 36, b.cor, CONTORNO) +
      rosto(b, fechado),
  )
}

export const NOMES_ANIMAIS = Object.keys(BICHOS)

export function animal(nome) {
  const b = BICHOS[nome]
  const aberto = desenhar(b, false)
  const fechado = desenhar(b, true)
  return { frames: [aberto, fechado], seq: [0, 0, 0, 0, 0, 0, 0, 1], fps: 4, px: 112 }
}
// Peças para desenhar em SVG (viewBox 100x100). Tudo é código: nenhum arquivo de imagem.
export const TRACO = '#3b2a1a'

export const svg = (interno) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${interno}</svg>`

const attrs = (extra) => (extra ? ` ${extra}` : '')

export const circulo = (cx, cy, r, fill, extra = '') =>
  `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}"${attrs(extra)}/>`

export const elipse = (cx, cy, rx, ry, fill, extra = '') =>
  `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}"${attrs(extra)}/>`

export const ret = (x, y, w, h, fill, rx = 0, extra = '') =>
  `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}"${attrs(extra)}/>`

// Caminho com contorno; sem `fill` vira só um traço.
// `stroke` pode ser uma cor ou já um trecho pronto de atributos (ex.: 'stroke="#3b2a1a" ...').
export const cam = (d, fill = 'none', stroke = TRACO, largura = 3, extra = '') => {
  const contorno = stroke.startsWith('stroke=') ? stroke : `stroke="${stroke}" stroke-width="${largura}"`
  return `<path d="${d}" fill="${fill}" ${contorno} stroke-linecap="round" stroke-linejoin="round"${attrs(extra)}/>`
}

export const grupo = (interno, transform) => `<g transform="${transform}">${interno}</g>`

export const gira = (interno, graus, cx = 50, cy = 50) => grupo(interno, `rotate(${graus} ${cx} ${cy})`)

// Cores do conjunto
export const COR = {
  amarelo: '#ffd23f',
  amareloBorda: '#d99a14',
  vermelho: '#e8554e',
  azul: '#3f8fd9',
  azulClaro: '#bfe3ff',
  verde: '#5cb85c',
  verdeEscuro: '#3a8a3a',
  roxo: '#7b4bb8',
  laranja: '#f39a3d',
  marrom: '#9a6b3f',
  cinza: '#78909c',
  cinzaClaro: '#cfd8dc',
  branco: '#ffffff',
  rosa: '#ff8fb1',
}
import { ARTE, urlDoQuadro } from '../arte/index.js'

// Ponte entre a arte (SVG em src/arte) e o Phaser: carrega todas as imagens uma vez, cria
// as animações por quadros e entrega sprites prontos para as cenas.
export const chave = (id, quadro = 0) => `${id}#${quadro}`

export function carregarArte(scene) {
  for (const [id, desc] of Object.entries(ARTE)) {
    desc.frames.forEach((_, i) => {
      scene.load.svg(chave(id, i), urlDoQuadro(id, i), { width: desc.px, height: desc.px })
    })
  }
}

export function criarAnimacoes(scene) {
  for (const [id, desc] of Object.entries(ARTE)) {
    if (desc.frames.length < 2) continue
    const sequencia = desc.seq ?? desc.frames.map((_, i) => i)
    scene.anims.create({
      key: id,
      frames: sequencia.map((i) => ({ key: chave(id, i) })),
      frameRate: desc.fps ?? 6,
      repeat: -1,
    })
  }
}

const animado = (scene, id) => ARTE[id].frames.length > 1 && scene.ctx?.efeitos !== false

// Sprite quadrado de `tamanho` pixels. Se a arte tem vários quadros, anima (a menos que
// `parado`, ou que "Reduzir efeitos" esteja ligado).
export function imagem(scene, x, y, id, tamanho, { parado = false } = {}) {
  if (!ARTE[id]) throw new Error(`Arte inexistente: ${id}`)
  const sprite = scene.add.sprite(x, y, chave(id, 0)).setDisplaySize(tamanho, tamanho)
  sprite.arteId = id
  if (!parado && animado(scene, id)) sprite.play(id)
  return sprite
}

// Troca o desenho de um sprite mantendo o tamanho na tela.
export function trocarImagem(sprite, id, { parado = false } = {}) {
  const { displayWidth, displayHeight } = sprite
  sprite.stop()
  sprite.setTexture(chave(id, 0))
  sprite.setDisplaySize(displayWidth, displayHeight)
  sprite.arteId = id
  if (!parado && animado(sprite.scene, id)) sprite.play(id)
}

// Ver imagem parada (primeiro quadro) ou animada, conforme o personagem anda.
export function animar(sprite, ligado) {
  if (!animado(sprite.scene, sprite.arteId) || sprite.animando === ligado) return
  sprite.animando = ligado
  if (ligado) sprite.play(sprite.arteId)
  else {
    sprite.stop()
    sprite.setTexture(chave(sprite.arteId, 0))
  }
}
import Phaser from 'phaser'
import { carregarArte, criarAnimacoes } from './arte.js'

// Carrega toda a arte (SVG desenhados em código) e inicia a cena do jogo escolhido.
export default class Boot extends Phaser.Scene {
  constructor() {
    super('Boot')
  }

  preload() {
    this.cameras.main.setBackgroundColor('#1f2a38')
    const texto = this.add
      .text(400, 225, 'Carregando...', { fontFamily: 'Fredoka, sans-serif', fontSize: '28px', color: '#ffffff' })
      .setOrigin(0.5)
    this.load.on('progress', (v) => texto.setText(`Carregando... ${Math.round(v * 100)}%`))
    carregarArte(this)
  }

  create() {
    criarAnimacoes(this)
    this.scene.start(this.registry.get('cena'))
  }
}
import { chave } from './arte.js'

// Efeitos visuais de recompensa e de "vida" do cenário. Todos respeitam a opção
// "Reduzir efeitos" (ctx.efeitos = false): nesse caso não animam nada. As animações de
// escala são relativas à escala atual, porque os sprites têm tamanho em pixels.
const PARTICULAS = ['p_estrela', 'p_coracao', 'p_brilho', 'p_bolinha', 'p_fita']
const entre = (a, b) => a + Math.random() * (b - a)

// Explosão de estrelinhas e confete. `fixo` = coordenadas da tela, em vez do mundo da fase.
export function confete(scene, x, y, { quantidade = 16, espalhar = 100, fixo = false } = {}) {
  if (!scene.ctx.efeitos) return
  for (let i = 0; i < quantidade; i++) {
    const tamanho = entre(16, 30)
    const base = tamanho / 48 // as partículas são rasterizadas em 48 px
    const p = scene.add.image(x, y, chave(PARTICULAS[i % PARTICULAS.length])).setScale(base).setDepth(60)
    if (fixo) p.setScrollFactor(0)
    const angulo = entre(0, Math.PI * 2)
    const distancia = espalhar * entre(0.5, 1.2)
    const duracao = entre(800, 1300)
    scene.tweens.add({
      targets: p,
      x: x + Math.cos(angulo) * distancia,
      y: y + Math.sin(angulo) * distancia - 30,
      angle: entre(-180, 180),
      scale: base * 0.6,
      duration: duracao,
      ease: 'Cubic.Out',
      onComplete: () => p.destroy(),
    })
    // some só na segunda metade, para o confete ficar visível enquanto voa
    scene.tweens.add({ targets: p, alpha: 0, delay: duracao * 0.5, duration: duracao * 0.5 })
  }
}

// Várias explosões espalhadas pela tela, para as celebrações.
export function chuvaDeConfete(scene, rodadas = 4) {
  for (let i = 0; i < rodadas; i++) {
    scene.time.delayedCall(i * 260, () =>
      confete(scene, entre(120, 680), entre(80, 260), { quantidade: 14, espalhar: 110, fixo: true }),
    )
  }
}

// "Pulinho de alegria": estica e volta.
export function estourar(scene, alvo, forca = 1.3) {
  if (!scene.ctx.efeitos) return
  scene.tweens.add({
    targets: alvo,
    scaleX: alvo.scaleX * forca,
    scaleY: alvo.scaleY * forca,
    duration: 110,
    yoyo: true,
    ease: 'Quad.Out',
  })
}

// Balanço rápido de lado a lado (um "opa" gentil ou um aceno).
export function balancar(scene, alvo, graus = 10) {
  if (!scene.ctx.efeitos) return
  scene.tweens.add({
  osc.stop(t + duracao + 0.05)
}

export function configurarAudio({ sons, musica }) {
  tocarSons = sons
  tocarMusica = musica
  if (!musica) pararMusica()
}

const efeito = (tocar) => () => {
  if (tocarSons) tocar()
}

const escala = (freqs, passo, duracao, opcoes) =>
