import Phaser from 'phaser'
import { FONTE, RAIO, botao, caixaTexto, criarHud, telaFinal } from '../../compartilhado/kit-phaser/ui.js'
import { imagem } from '../../compartilhado/kit-phaser/arte.js'
import { sons } from '../../compartilhado/kit-phaser/audio.js'
import { confete, estourar, nuvens, respirar } from '../../compartilhado/kit-phaser/efeitos.js'
import { carregarArteTortas, chaveTorta, criarAnimacoesTortas, desenhar } from './arte.js'
import { AVISO, TORTAS_PARA_ENCHER, configDoNivel, deveAbrirGuarda, duracaoGuarda, proximaAcao } from './regras.js'

const GATO = { x: 190, y: 290 }
const GUAXINIM = { x: 610, y: 285 }
const ESCUDO = { x: 78, y: 392, r: 48 }
const CHAO = 372

// Jogo cooperativo: o adulto defende com a bandeja do gatinho (botão de escudo ou espaço) e
// a criança lança a torta (toque ou clique em qualquer outro lugar). Cada defesa dá uma torta.
// O guaxinim avisa com um balão antes de lançar e antes de abrir a guarda. Errar não tira
// nada: o gatinho leva um respingo de chantili, ou a torta cai da bandeja do guaxinim.
export default class GuerraTortas extends Phaser.Scene {
  constructor() {
    super('GuerraTortas')
  }

  init() {
    this.ctx = this.registry.get('ctx')
    this.cfg = configDoNivel(this.ctx.nivel)
  }

  preload() {
    carregarArteTortas(this)
  }

  create() {
    criarAnimacoesTortas(this)
    this.input.addPointer(2) // adulto e criança tocam ao mesmo tempo no tablet
    this.cameras.main.setBackgroundColor(this.ctx.hiperfoco.cor)
    nuvens(this, 4)
    this.add.rectangle(400, CHAO + 39, 800, 78, 0x000000, 0.18)

    this.jogando = false
    this.fim = false
    this.temTorta = false
    this.esperandoDesde = null
    this.bandejaErguida = false
    this.guardaErguida = false
    this.tortaDaCriancaVoando = false
    this.ultimoLancamento = -Infinity
    this.comidas = 0
    this.estadoGuaxinim = 'aberto'
    this.timerGuaxinim = null

    this.hud = criarHud(this, this.ctx)
    this.criarPersonagens()
    this.criarMedidor()
    this.criarEscudo()

    this.input.on('pointerdown', (_, sobre) => {
      if (!sobre.includes(this.escudo)) this.lancar()
    })
    this.input.keyboard?.addCapture('SPACE')
    this.input.keyboard?.on('keydown-SPACE', () => this.defender())

    this.mostrarPapeis()
  }

  duracao(ms) {
    return this.ctx.efeitos ? ms : 1
  }

  // ---------- montagem ----------

  criarPersonagens() {
    this.gato = imagem(this, GATO.x, GATO.y, 'amigo_gato', 150).setDepth(2)
    respirar(this, this.gato, 0.03)
    this.guaxinim = this.add.sprite(GUAXINIM.x, GUAXINIM.y, chaveTorta('guaxinim')).setDisplaySize(170, 170).setDepth(2)
    desenhar(this.guaxinim, 'guaxinim', this.ctx.efeitos)
    this.escalaGuaxinim = this.guaxinim.scaleX

    this.bandejaGato = this.add.image(0, 0, chaveTorta('bandeja')).setDepth(4)
    this.bandejaGuaxinim = this.add.image(0, 0, chaveTorta('bandeja')).setDepth(4)
    this.posicionarBandeja(this.bandejaGato, GATO, 1, false, false)
    this.posicionarBandeja(this.bandejaGuaxinim, GUAXINIM, -1, false, false)

    // a torta que a criança tem para lançar fica na mão do gatinho
    this.tortaNaMao = this.add.image(GATO.x - 62, GATO.y + 30, chaveTorta('torta')).setDisplaySize(64, 64).setDepth(5).setVisible(false)

    // balão de aviso acima do guaxinim
    const fundo = this.add.rectangle(0, 0, 84, 70, 0xffffff, 0.95).setRounded(RAIO)
    const ponta = this.add.triangle(0, 42, -10, 0, 10, 0, 0, 14, 0xffffff, 0.95)
    this.iconeBalao = this.add.image(0, 0, chaveTorta('torta')).setDisplaySize(54, 54)
    this.balao = this.add.container(GUAXINIM.x, GUAXINIM.y - 140, [fundo, ponta, this.iconeBalao]).setDepth(6).setVisible(false)
  }

  // `lado` 1 = bandeja à direita do personagem (gatinho), -1 = à esquerda (guaxinim).
  // Baixa, a bandeja fica deitada ao lado do corpo; erguida, fica de frente, como escudo.
  posicionarBandeja(bandeja, dono, lado, erguida, animar = true) {
    const alvo = erguida
      ? { x: dono.x + lado * 78, y: dono.y - 8, displayWidth: 104, displayHeight: 104 }
      : { x: dono.x + lado * 66, y: dono.y + 58, displayWidth: 70, displayHeight: 22 }
    this.tweens.killTweensOf(bandeja)
    if (!animar || !this.ctx.efeitos) {
      bandeja.setPosition(alvo.x, alvo.y).setDisplaySize(alvo.displayWidth, alvo.displayHeight)
      return
    }
    this.tweens.add({ targets: bandeja, ...alvo, duration: 140, ease: 'Quad.Out' })
  }

  criarMedidor() {
    // barriga do guaxinim: uma casinha por torta comida
    this.add.rectangle(792, 4, 250, 52, 0x000000, 0.4).setOrigin(1, 0).setRounded(RAIO)
    this.casinhas = []
    for (let i = 0; i < TORTAS_PARA_ENCHER; i++) {
      const x = 572 + i * 44
      this.add.circle(x, 30, 18, 0xffffff, 0.25)
      this.casinhas.push(this.add.image(x, 30, chaveTorta('torta')).setDisplaySize(36, 36).setAlpha(0))
    }
  }

  criarEscudo() {
    this.escudo = this.add.circle(ESCUDO.x, ESCUDO.y, ESCUDO.r, 0x2f6fed).setStrokeStyle(4, 0xffffff).setDepth(8)
    this.escudo.setInteractive({ useHandCursor: true })
    this.add.image(ESCUDO.x, ESCUDO.y - 4, chaveTorta('bandeja')).setDisplaySize(62, 62).setDepth(9)
    this.add
      .text(ESCUDO.x + ESCUDO.r + 10, ESCUDO.y + 18, 'adulto: espaço', { fontFamily: FONTE, fontSize: '15px', color: '#ffffff' })
      .setOrigin(0, 0.5)
      .setAlpha(0.8)
      .setDepth(9)
    this.escudo.on('pointerdown', () => this.defender())
  }

  // Tela inicial sem depender de leitura: figuras mostram quem defende e quem lança.
  mostrarPapeis() {
    const itens = []
    const add = (o) => (itens.push(o.setDepth(50)), o)
    add(this.add.rectangle(400, 225, 800, 450, 0x000000, 0.72))
    const cartao = (x, pessoa, acao, titulo, gesto) => {
      add(this.add.rectangle(x, 205, 300, 250, 0xffffff, 0.14).setRounded(RAIO + 6))
      add(this.add.image(x - 60, 190, chaveTorta(pessoa)).setDisplaySize(110, 110))
      add(this.add.image(x + 62, 190, chaveTorta(acao)).setDisplaySize(90, 90))
      add(this.add.text(x, 278, titulo, { fontFamily: FONTE, fontSize: '28px', color: '#ffffff' }).setOrigin(0.5))
      add(this.add.text(x, 312, gesto, { fontFamily: FONTE, fontSize: '17px', color: '#ffe9a8' }).setOrigin(0.5))
    }
    cartao(235, 'adulto', 'bandeja', 'Você defende', 'botão azul ou espaço')
    cartao(565, 'crianca', 'torta', 'Você lança', 'toque ou clique na tela')
    const comecar = botao(this, 400, 395, 240, 64, 'Começar', () => {
      itens.forEach((o) => o.destroy())
      comecar.r.destroy()
      comecar.t.destroy()
      // o toque em "Começar" não pode virar um lançamento
      this.time.delayedCall(50, () => this.iniciar())
    }, 0x2e9e5b)
    comecar.r.setDepth(52)
    comecar.t.setDepth(53)
  }

  iniciar() {
    this.jogando = true
    // a primeira ação é sempre um lançamento, para a dupla ganhar a primeira torta logo
    this.agendar(1200, () => this.avisarLancamento())
  }

  agendar(ms, acao) {
    this.timerGuaxinim?.remove()
    this.timerGuaxinim = this.time.delayedCall(ms, () => {
      if (!this.fim) acao()
    })
  }

  // ---------- guaxinim ----------

  decidir() {
    const acao = proximaAcao({
      agora: this.time.now,
      ultimoLancamento: this.ultimoLancamento,
      esperandoDesde: this.esperandoDesde,
      config: this.cfg,
    })
    if (acao === 'lancar') this.avisarLancamento()
    else if (acao === 'defender') this.erguerGuarda()
    else this.ficarAberto()
  }

  ficarAberto() {
    this.estadoGuaxinim = 'aberto'
    this.agendar(this.cfg.aberto, () => this.decidir())
  }

  mostrarBalao(icone) {
    this.iconeBalao.setTexture(chaveTorta(icone)).setDisplaySize(54, 54)
    this.balao.setVisible(true)
    // leve balanço do guaxinim junto com o balão; sem piscar
    if (this.ctx.efeitos) {
      this.tweens.add({ targets: this.guaxinim, angle: { from: -5, to: 5 }, duration: 150, yoyo: true, repeat: 1, onComplete: () => this.guaxinim.setAngle(0) })
    }
  }

  avisarLancamento() {
    this.estadoGuaxinim = 'avisando'
    this.mostrarBalao('torta')
    this.agendar(AVISO, () => this.lancarDoGuaxinim())
  }

  lancarDoGuaxinim() {
    this.balao.setVisible(false)
    this.ultimoLancamento = this.time.now
    const torta = this.add.image(GUAXINIM.x - 60, GUAXINIM.y - 10, chaveTorta('torta')).setDisplaySize(70, 70).setDepth(7)
    this.voar(torta, GATO.x + 78, GATO.y - 8, this.cfg.voo, () => this.tortaChegouNoGato(torta))
    // logo depois de lançar, o guaxinim fica desprotegido
    this.ficarAberto()
  }

  erguerGuarda() {
    this.estadoGuaxinim = 'guarda'
    this.guardaErguida = true
    this.posicionarBandeja(this.bandejaGuaxinim, GUAXINIM, -1, true)
    this.agendar(duracaoGuarda(), () => this.avisarAbertura())
  }

  avisarAbertura() {
    this.estadoGuaxinim = 'abrindo'
    this.mostrarBalao('bandeja_baixo')
    this.agendar(AVISO, () => {
      this.balao.setVisible(false)
      this.guardaErguida = false
      this.posicionarBandeja(this.bandejaGuaxinim, GUAXINIM, -1, false)
      this.ficarAberto()
    })
  }

  update() {
    if (this.fim || this.estadoGuaxinim !== 'guarda') return
    if (deveAbrirGuarda({ agora: this.time.now, esperandoDesde: this.esperandoDesde, config: this.cfg })) this.avisarAbertura()
  }

  // ---------- dupla ----------

  // Torta em arco; a chegada decide o que acontece.
  voar(torta, x, y, ms, aoChegar) {
    const inicio = { x: torta.x, y: torta.y }
    const caminho = { t: 0 }
    this.tweens.add({
      targets: caminho,
      t: 1,
      duration: ms,
      onUpdate: () => {
        const t = caminho.t
        torta.setPosition(Phaser.Math.Linear(inicio.x, x, t), Phaser.Math.Linear(inicio.y, y, t) - Math.sin(t * Math.PI) * 70)
        if (this.ctx.efeitos) torta.setAngle(t * 360 * Math.sign(x - inicio.x))
      },
      onComplete: () => (this.fim ? torta.destroy() : aoChegar()),
    })
  }

  defender() {
    // defender e lançar não acontecem juntos
    if (!this.jogando || this.fim || this.bandejaErguida || this.tortaDaCriancaVoando) return
    this.bandejaErguida = true
    this.posicionarBandeja(this.bandejaGato, GATO, 1, true)
    this.time.delayedCall(this.cfg.bandeja, () => {
      this.bandejaErguida = false
      this.posicionarBandeja(this.bandejaGato, GATO, 1, false)
    })
  }

  tortaChegouNoGato(torta) {
    if (this.bandejaErguida) {
      // defesa certa: a torta fica para a criança lançar
      this.hud.acerto({ x: GATO.x + 78, y: GATO.y - 8 })
      torta.destroy()
      if (!this.temTorta) {
        this.temTorta = true
        this.esperandoDesde = this.time.now
        this.tortaNaMao.setVisible(true)
        estourar(this, this.tortaNaMao, 1.25)
      }
      return
    }
    // sem defesa: só um respingo de chantili, e o gatinho ri
    this.hud.erro()
    torta.destroy()
    const respingo = this.add.image(GATO.x, GATO.y - 10, chaveTorta('chantili')).setDisplaySize(110, 110).setDepth(6)
    estourar(this, this.gato, 1.12)
    this.tweens.add({ targets: respingo, alpha: 0, delay: 900, duration: this.duracao(300), onComplete: () => respingo.destroy() })
  }

  lancar() {
    if (!this.jogando || this.fim || !this.temTorta || this.bandejaErguida || this.tortaDaCriancaVoando) return
    this.temTorta = false
    this.esperandoDesde = null
    this.tortaDaCriancaVoando = true
    this.tortaNaMao.setVisible(false)
    const torta = this.add.image(this.tortaNaMao.x, this.tortaNaMao.y, chaveTorta('torta')).setDisplaySize(64, 64).setDepth(7)
    this.voar(torta, GUAXINIM.x - 20, GUAXINIM.y - 20, 500, () => this.tortaChegouNoGuaxinim(torta))
  }

  tortaChegouNoGuaxinim(torta) {
    this.tortaDaCriancaVoando = false
    if (this.guardaErguida) {
      // bateu na bandeja: cai no chão e o guaxinim faz careta
      this.hud.erro()
      const idCareta = this.comidas >= 3 ? 'guaxinim_cheio_careta' : 'guaxinim_careta'
      desenhar(this.guaxinim, idCareta, this.ctx.efeitos)
      this.tweens.add({
        targets: torta,
        x: torta.x - 50,
        y: CHAO + 20,
        duration: this.duracao(450),
        ease: 'Quad.In',
        onComplete: () => this.tweens.add({ targets: torta, alpha: 0, delay: 500, duration: 300, onComplete: () => torta.destroy() }),
      })
      this.time.delayedCall(900, () => !this.fim && desenhar(this.guaxinim, this.desenhoDoGuaxinim(), this.ctx.efeitos))
      return
    }
    // acertou: o guaxinim come a torta e a barriga enche um pouco
    torta.destroy()
    this.hud.acerto({ x: GUAXINIM.x, y: GUAXINIM.y - 40 })
    this.casinhas[this.comidas].setAlpha(1)
    estourar(this, this.casinhas[this.comidas], 1.3)
    this.comidas++
    if (this.comidas >= TORTAS_PARA_ENCHER) return this.terminar()
    desenhar(this.guaxinim, this.desenhoDoGuaxinim(), this.ctx.efeitos)
    estourar(this, this.guaxinim, 1.12)
  }

  desenhoDoGuaxinim() {
    return this.comidas >= 3 ? 'guaxinim_cheio' : 'guaxinim'
  }

  // Final: o guaxinim fica cheio, deita e dorme; os dois comemoram.
  terminar() {
    this.fim = true
    this.timerGuaxinim?.remove()
    this.balao.setVisible(false)
    this.guardaErguida = false
    this.posicionarBandeja(this.bandejaGuaxinim, GUAXINIM, -1, false)
    this.bandejaGuaxinim.setVisible(false)
    desenhar(this.guaxinim, 'guaxinim_dormindo', false)
    const deitado = { angle: -80, y: CHAO - 40 }
    if (this.ctx.efeitos) this.tweens.add({ targets: this.guaxinim, ...deitado, duration: 300, ease: 'Quad.Out' })
    else this.guaxinim.setAngle(deitado.angle).setY(deitado.y)
    caixaTexto(this, GUAXINIM.x + 40, GUAXINIM.y - 110, 'Zzz', { fontSize: '30px', color: '#ffffff' }, { px: 12, py: 4, alpha: 0.35 })
    estourar(this, this.gato, 1.25)
    confete(this, GATO.x, GATO.y - 40, { quantidade: 20 })
    sons.estrela()
    this.time.delayedCall(2200, () => telaFinal(this, this.ctx, 'Vocês conseguiram!\nO guaxinim encheu a barriga e dormiu.'))
  }
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { AVISO, GUARDA, NIVEIS, configDoNivel, deveAbrirGuarda, duracaoGuarda, proximaAcao } from '../src/jogos/guerra-tortas/regras.js'
import { ARTE_TORTAS } from '../src/jogos/guerra-tortas/arte.js'

const sempre = (v) => () => v

test('nível fora de 1 a 3 cai no nível mais próximo', () => {
  assert.equal(configDoNivel(0), NIVEIS[1])
  assert.equal(configDoNivel(undefined), NIVEIS[1])
  assert.equal(configDoNivel(2), NIVEIS[2])
  assert.equal(configDoNivel(9), NIVEIS[3])
})

test('o nível 1 é o mais calmo', () => {
  assert.ok(NIVEIS[1].voo > NIVEIS[3].voo, 'tortas mais lentas')
  assert.ok(NIVEIS[1].bandeja > NIVEIS[3].bandeja, 'janela de defesa maior')
  assert.ok(NIVEIS[1].aberto > NIVEIS[3].aberto, 'guaxinim desprotegido por mais tempo')
  assert.deepEqual([1, 2, 3].map((n) => NIVEIS[n].esperaMax), [2000, 3000, 4000])
})

test('o guaxinim só lança depois do tempo mínimo desde o último lançamento', () => {
  const config = NIVEIS[1]
  const base = { ultimoLancamento: 0, esperandoDesde: null, config, aleatorio: sempre(0) }
  assert.notEqual(proximaAcao({ ...base, agora: config.intervaloLancar - 1 }), 'lancar')
  assert.equal(proximaAcao({ ...base, agora: config.intervaloLancar }), 'lancar')
})

test('com a criança esperando demais, o guaxinim não ergue a guarda', () => {
  const config = NIVEIS[1]
  const agora = 10_000
  const esperandoDesde = agora - config.esperaMax
  // aleatorio 0 escolheria defender, se pudesse
  const acao = proximaAcao({ agora, ultimoLancamento: agora, esperandoDesde, config, aleatorio: sempre(0) })
  assert.equal(acao, 'aberto')
})

test('a guarda abre a tempo de cumprir a espera máxima', () => {
  const config = NIVEIS[2]
  assert.equal(deveAbrirGuarda({ agora: 5000, esperandoDesde: null, config }), false)
  assert.equal(deveAbrirGuarda({ agora: 1000 + config.esperaMax - AVISO - 1, esperandoDesde: 1000, config }), false)
  // começa a abrir aqui; com o aviso, fica desprotegido exatamente em esperaMax
  assert.equal(deveAbrirGuarda({ agora: 1000 + config.esperaMax - AVISO, esperandoDesde: 1000, config }), true)
})

test('a guarda dura entre o mínimo e o máximo', () => {
  assert.equal(duracaoGuarda(sempre(0)), GUARDA.min)
  assert.equal(duracaoGuarda(sempre(1)), GUARDA.max)
})

test('a arte do jogo é SVG válido', () => {
  for (const [id, desc] of Object.entries(ARTE_TORTAS)) {
    assert.ok(desc.frames.length >= 1, id)
    for (const f of desc.frames) assert.match(f, /^<svg [^>]+>.*<\/svg>$/s, id)
  }
})

