async () => {
  const s = window.__phaser.scene.getScene('GuerraTortas');
  const c = document.querySelector('canvas').getBoundingClientRect();
  const sx = c.width / 800, sy = c.height / 450;
  const clicar = (x, y) => { for (const t of ['pointerdown','pointerup']) document.querySelector('canvas').dispatchEvent(new PointerEvent(t, { clientX: c.left + x*sx, clientY: c.top + y*sy, bubbles: true, pointerId: 1, isPrimary: true, pointerType: 'mouse' })); };
  clicar(400, 395); // Começar
  const espera = (ms) => new Promise(r => setTimeout(r, ms));
  await espera(300);
  const log = [{ jogando: s.jogando }];
  // espera o guaxinim lançar e defende no meio do voo
  while (s.estadoGuaxinim !== 'avisando') await espera(50);
  log.push({ balao: s.balao.visible });
  await espera(600 + 1200);
  window.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', code: 'Space', keyCode: 32 }));
  log.push({ bandejaErguida: s.bandejaErguida });
  await espera(1500);
  log.push({ temTorta: s.temTorta, tortaVisivel: s.tortaNaMao.visible });
  return log;
}

