async (page) => {
  await page.goto('http://127.0.0.1:5195/jogo.html?id=guerra-tortas&tema=trem');
  await page.waitForFunction(() => window.__phaser?.scene.getScene('GuerraTortas')?.escudo, null, { timeout: 15000 });
  const box = await page.locator('canvas').boundingBox();
  const p = (x, y) => [box.x + x * box.width / 800, box.y + y * box.height / 450];
  const est = () => page.evaluate(() => { const s = window.__phaser.scene.getScene('GuerraTortas'); return { jogando: s.jogando, g: s.estadoGuaxinim, guarda: s.guardaErguida, bandeja: s.bandejaErguida, temTorta: s.temTorta, comidas: s.comidas, t: Math.round(s.time.now) }; });
  const log = [];
  await page.mouse.click(...p(400, 395));
  await page.waitForTimeout(200);
  log.push(['apos comecar', await est()]);
  // primeira torta do guaxinim: aviso em 1200ms, voo 2200ms
  await page.waitForFunction(() => window.__phaser.scene.getScene('GuerraTortas').estadoGuaxinim === 'avisando', null, { timeout: 5000 });
  log.push(['aviso', await est()]);
  await page.waitForTimeout(600 + 1300);
  await page.keyboard.press('Space');
  log.push(['espaco', await est()]);
  await page.waitForTimeout(1200);
  log.push(['defendeu?', await est()]);
  await page.screenshot({ path: '.playwright-mcp/gt-torta.png' });
  // criança lança quando a guarda estiver baixa
  await page.waitForFunction(() => !window.__phaser.scene.getScene('GuerraTortas').guardaErguida && !window.__phaser.scene.getScene('GuerraTortas').bandejaErguida, null, { timeout: 6000 });
  await page.mouse.click(...p(400, 200));
  await page.waitForTimeout(700);
  log.push(['lancou', await est()]);
  // tecla com a criança segurando torta não deve travar; verifica garantia de espera
  return log;
}

