await (async (page) => {
  const logs = [];
  page.on('console', (m) => { if (/completed|abandoned|status/.test(m.text())) logs.push(m.text()); });
  await page.goto('http://127.0.0.1:5195/jogo.html?id=guerra-tortas&tema=dinossauro');
  await page.waitForFunction(() => window.__phaser?.scene.getScene('GuerraTortas')?.escudo, null, { timeout: 15000 });
  return await page.evaluate(async () => {
    const s = window.__phaser.scene.getScene('GuerraTortas');
    s.iniciar(); s.children.list.filter(o => o.depth >= 50).forEach(o => o.destroy());
    const espera = (ms) => new Promise(r => setTimeout(r, ms));
    let maxEspera = 0, bloqueios = 0, respingos = 0, inicio = performance.now();
    // vigia: defende quando uma torta do guaxinim está perto do gato; criança lança assim que a guarda baixa
    while (!s.fim && performance.now() - inicio < 90000) {
      const voando = s.children.list.filter(o => o.texture?.key === 'gt_torta#0' && o !== s.tortaNaMao && !o.ehMedidor && o.depth === 7 && o.x < 330 && o.x > 260);
      if (voando.length) s.defender();
      if (s.temTorta && s.esperandoDesde !== null) {
        const w = s.time.now - s.esperandoDesde;
        if (!s.guardaErguida && s.estadoGuaxinim !== 'abrindo') { maxEspera = Math.max(maxEspera, w); s.lancar(); }
      }
      await espera(40);
    }
    await espera(2600);
    return { fim: s.fim, comidas: s.comidas, maxEsperaAteAbrir: Math.round(maxEspera), segundos: Math.round((performance.now() - inicio) / 1000) };
  }).then(async (r) => { await page.screenshot({ path: '.playwright-mcp/gt-final.png' }); return { ...r, logs }; });
})(page);
```
