async (page) => {
  const erros = [];
  page.on('pageerror', (e) => erros.push(e.message));
  return await page.evaluate(async () => {
    const espera = (ms) => new Promise(r => setTimeout(r, ms));
    let s = window.__phaser.scene.getScene('GuerraTortas');
    s.scene.restart();
    await espera(500);
    s = window.__phaser.scene.getScene('GuerraTortas');
    const r = { reiniciou: s.comidas === 0 && !s.fim };
    s.children.list.filter(o => o.depth >= 50).forEach(o => o.destroy()); s.iniciar();
    // sem defender: respingo
    while (s.ultimoLancamento < 0) await espera(50);
    await espera(2400);
    r.respingo = s.children.list.some(o => o.texture?.key === 'gt_chantili#0');
    // dá uma torta e força a guarda para testar a torta na bandeja
    s.temTorta = true; s.esperandoDesde = s.time.now; s.tortaNaMao.setVisible(true);
    s.timerGuaxinim?.remove(); s.erguerGuarda(); s.lancar();
    await espera(650);
    r.careta = s.guaxinim.texture.key; r.comidasAposBloqueio = s.comidas;
    await espera(1800);
    r.guardaAbriuPelaGarantia = !s.guardaErguida;
    return r;
  }).then((r) => ({ ...r, erros }));
}

